from ute_common_config.config import Config
from ute_common_validator.validator import IsString, IsIpAddress, IsOneOf

from .base import PduMixin


class Host(Config):

    def __init__(self, addr='127.0.0.1', username='ute', password='ute'):
        """
        :param string   addr:       Host IP address.
        :param string   username:   Login to host
        :param string   password:   Password to host
        """
        super(Host, self).__init__()

        ip_validator = IsIpAddress()

        self._set_attr("addr", addr, ip_validator)
        self._set_attr("username", username, IsString())
        self._set_attr("password", password, IsString())


class Pdu(PduMixin):

    def __init__(self, addr, model, outlet):
        """
        :param string    addr:     PDU IP address.
        :param string    model:    PDU model. Supported values: APC, APC16, SWH, ATEN, ATEN24, DCS, BBOX, MOXA, FACOM,
                                   PKC, PKC16, S7, SHCL, FPFH, EPC, EPCNC, MYCOMP, HBTE.
        :param integer   outlet:   PDU outlet number.
        """
        super(Pdu, self).__init__()

        pdu_type_validator = IsOneOf(*self.PDU_TYPES_ALLOWED)
        outlet_validator = IsOneOf(*self.get_allowed_pdu_outlets(model))
        ip_validator = IsIpAddress()

        self._set_attr("addr", addr, ip_validator)
        self._set_attr("model", model, pdu_type_validator)
        self._set_attr("outlet", outlet, outlet_validator)
